select id, amount, status, max(amount) over w_ordered as running_max_amount, count(amount) over w_ordered as running_count_amount, min(amount) over w_ordered as running_min_amount, avg(amount) over w_part as amount_avg_5 from payments where hour(paid_at) between 7 and 14 window w_ordered as (partition by method order by paid_at, id rows between unbounded preceding and current row), w_part as (partition by status, method order by paid_at, id rows between 5 preceding and current row);
